# Homebrew formula for kosa8.
#
# Regenerated by CI on every release (see the kosa8-releases workflow), so
# `brew upgrade kosa8` tracks new versions without a manual edit.
class Kosa8 < Formula
  desc "Run AI coding assistants in sealed machines you can save and copy"
  homepage "https://kosa8.com"
  license "Apache-2.0"
  version "0.11.0"

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/AzmxAI/kosa8-releases/releases/download/v#{version}/kosa8_#{version}_darwin_arm64.zip"
      sha256 "6121a28d5f530549ea1bcc9f1dd397774be9347a5400a5cd1b02ad7963950fa5"
    else
      url "https://github.com/AzmxAI/kosa8-releases/releases/download/v#{version}/kosa8_#{version}_darwin_amd64.zip"
      sha256 "92685e5d3a6113179f6f51fde4c5d6f1b365d6eaaa5271cbdd92068e35be61b9"
    end
  end

  def install
    bin.install "kosa8"
    # kosa8d only ships for Apple Silicon: it drives Virtualization.framework,
    # which needs an arm64 Mac. Intel Macs get the CLI as a remote client.
    bin.install "kosa8d" if Hardware::CPU.arm? && File.exist?("kosa8d")
  end

  def caveats
    return unless Hardware::CPU.intel?
    <<~EOS
      This Mac has an Intel processor, so it cannot run containers itself.
      kosa8 is installed as a client — point it at an Apple Silicon Mac:

        export KOSA8_HOST=https://your-mac.example.com
        export KOSA8_TOKEN=…
    EOS
  end

  test do
    assert_match "kosa8 client", shell_output("#{bin}/kosa8 version")
  end
end
